#!/usr/bin/env python3
"""
Round 185o (culprits-tiles-more), 5 October 2026.

fao_fisheries.py also writes fish/fao_sharks.json (FAO's group Sharks,
rays, chimaeras, each country). isds_unctad.py writes every page and link it
tried to isds/build.json, checks a download is really excel, and reads a copy
uploaded by hand to isds/download/ first. Each file is written only if it
differs.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, sys

FILES = {'scripts/isds_unctad.py': '', 'scripts/fao_fisheries.py': ''}


def main():
    if not pathlib.Path("scripts").is_dir():
        sys.exit("round185o_tiles: run from the culprits-tiles-more repository root")
    changed = 0
    for path, b64 in FILES.items():
        data = base64.b64decode(b64)
        p = pathlib.Path(path)
        if p.exists() and p.read_bytes() == data:
            continue
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(data)
        changed += 1
        print(f"round185o_tiles: wrote {path}")
    if not changed:
        print("round185o_tiles: already applied")


if __name__ == "__main__":
    main()
